const MAX_TAGS = 50;

function PopularTagsList({ tags }) {
  return (
    <ul className="tag-list-items">
      {tags.slice(0, MAX_TAGS).map((name) => (
        <li key={name}>
          <button className="tag-pill tag-default" type="button">
            {name}
          </button>
        </li>
      ))}
    </ul>
  );
}

export default PopularTagsList;

